import{_ as l,b as t,c as e,g as a}from"./chunks/framework.86O3EbG5.js";const r="/images/build-a-llm/ch01-2.png",s="/images/build-a-llm/ch01-1.png",f=JSON.parse('{"title":"从零构建大模型（一）","description":"","frontmatter":{"title":"从零构建大模型（一）","subTitle":"理解大语言模型","author":"oasis","date":"2025-12-02T00:00:00.000Z","tags":["llm"]},"headers":[],"relativePath":"articles/ai/books/build-a-llm/1.md","filePath":"articles/ai/books/build-a-llm/1.md"}'),n={name:"articles/ai/books/build-a-llm/1.md"};function o(p,i,m,d,_,c){return t(),e("div",null,[...i[0]||(i[0]=[a('<h2 id="什么是大语言模型-llm" tabindex="-1">什么是大语言模型（LLM）</h2><p>大语言模型是一种用于理解、生成和响应类似人类语言文本的神经网络。其主要特征：</p><ol><li>深度神经网络</li><li>大规模文本数据训练</li></ol><p>由于大语言模型（LLM）能够生成文本，因此也被称为生成式人工智能（GenAI、Generative Artificial Intelligence）</p><p>大语言模型是深度学习技术的具体应用，深度学习是机器学习的一个分支，主要使用多层神经网络</p><h2 id="大语言模型的构建阶段" tabindex="-1">大语言模型的构建阶段</h2><p>大语言模型的构建通常包括预训练（pre-training）和微调（fine-tuning）。预训练是在大规模、多样化的数据集上进行的（网络资料、图书、研究论文等），目的是让大模型形成全面 的语言理解能力。</p><p>微调阶段会在规模较小的特定任务或领域数据集上对模型进行针对性训练，目的是进一步提升其特定能力（例如：代码生成能力、分类、文本总结、翻译等）。</p><p>大模型的微调是在标注数据集上进行训练，从而得到特定的能力。微调大模型最流行的两种方法：</p><ol><li>指令微调</li><li>分类任务微调</li></ol><p>人自出生之日便开始了预训练，自上学之后，便开启了微调。</p><h2 id="transformer-架构" tabindex="-1">Transformer 架构</h2><p>Transformer 架构由两个子模块构成：</p><ol><li>编码器：负责处理输入文本，将文本编码为一系列数值表示或向量，以捕捉上下文信息。上下文信息的捕捉动作，是自注意力机制（self-attention mechanism）实现的。</li><li>解码器：负责接收这些编码向量，并据此生成输出文本。</li></ol><p><img src="'+r+'" alt="Transformer架构"></p><h2 id="构建大语言模型路线图" tabindex="-1">构建大语言模型路线图</h2><p><img src="'+s+'" alt="build path"></p>',17)])])}const h=l(n,[["render",o]]);export{f as __pageData,h as default};
